package dev.eugheist.tc4modern;
import java.util.*;
import net.minecraft.core.*;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.world.*;
import net.minecraft.world.entity.*;
import net.minecraft.world.entity.item.ItemEntity;
import net.minecraft.world.item.*;
import net.minecraft.world.item.context.*;
import net.minecraft.world.level.block.Block;
import net.minecraft.world.phys.*;
import net.neoforged.bus.api.SubscribeEvent;
import net.neoforged.fml.common.EventBusSubscriber;
import thaumcraft.api.aspects.*;
@EventBusSubscriber(modid=TC4Modern.MODID,value=net.neoforged.api.distmarker.Dist.CLIENT)
final class BannerAudit {
 static int ticks;static volatile boolean passed;static final BlockPos POS=InfusionAudit.POS;
 static void check(boolean b,String message){if(!b)throw new IllegalStateException("TC4_BANNER FAIL "+message);System.out.println("TC4_BANNER PASS "+message);}
 static void prepare(ServerPlayer p){InfusionAudit.prepare(p);InfusionAudit.matrix.logic.crafting=false;var l=p.serverLevel();l.getEntitiesOfClass(ItemEntity.class,new AABB(POS).inflate(25)).forEach(Entity::discard);for(var slot:EquipmentSlot.values())if(slot.isArmor())p.setItemSlot(slot,ItemStack.EMPTY);var template=p.getInventory().items.stream().filter(WandData::isWand).findFirst().orElseThrow().copy();p.getInventory().clearContent();p.getInventory().selected=0;
  check(ResearchClues.matchesItemTrigger("BANNERS","tc4modern:crimson_banner"),"cult banner reveals original hidden research");
  for(int color=0;color<16;color++){int index=color;var r=ArcaneRecipes.entries().stream().filter(x->x.key().equals("Banner_"+index)).findFirst().orElseThrow();var grid=new ArrayList<ItemStack>(Collections.nCopies(9,ItemStack.EMPTY));for(int row=0;row<3;row++)for(int col=0;col<2;col++)grid.set(row*3+col,r.ingredients().get(row*2+col).getItems()[0].copy());check(r.matches(grid,Set.of("BANNERS"))&&!r.matches(grid,Set.of())&&r.cost().getAmount(Aspect.WATER)==5&&r.cost().getAmount(Aspect.EARTH)==5,"color"+color+" exact wool/stick/slab recipe5aqua5terra and research");var wand=template.copy();var expected=wand.copy();check(WandData.consumeCrafting(expected,r.cost(),true,p),"baseline vis cost "+color);var table=new SimpleContainer(10);for(int i=0;i<9;i++)table.setItem(i,grid.get(i));table.setItem(9,wand);var menu=new ArcaneWorkbenchMenu(0,p.getInventory(),net.minecraft.world.inventory.ContainerLevelAccess.NULL,table);var result=menu.slots.get(0);check(result.mayPickup(p)&&NoteData.tag(result.getItem()).getByte("color")==color,"native workbench output preserves color"+color);var crafted=result.remove(1);result.onTake(p,crafted);check(ItemStack.isSameItemSameComponents(wand,expected),"native workbench consumes exact discounted vis"+color);for(int i=0;i<9;i++)check(table.getItem(i).isEmpty(),"native workbench consumes ingredient"+color+":"+i);menu.removed(p);
   var pos=POS.offset(color%4*3-10,-2,color/4*3-10);l.setBlock(pos,net.minecraft.world.level.block.Blocks.AIR.defaultBlockState(),3);p.setItemInHand(InteractionHand.MAIN_HAND,crafted);var context=new BlockPlaceContext(p,InteractionHand.MAIN_HAND,crafted,new BlockHitResult(pos.below().getCenter().add(0,.5,0),Direction.UP,pos.below(),false));check(((BlockItem)crafted.getItem()).place(context).consumesAction(),"actual placement of crafted banner"+color);var banner=(CrimsonBanner.Entity)l.getBlockEntity(pos);check(banner.color==color&&l.getBlockState(pos).getCollisionShape(l,pos).isEmpty(),"placed color and no collision"+color);var crystal=LiquidDeath.crystal(Aspect.aspects.values().stream().sorted(Comparator.comparing(Aspect::getTag)).toList().get(color),2);p.setItemInHand(InteractionHand.MAIN_HAND,crystal);var hit=new BlockHitResult(pos.getCenter(),Direction.UP,pos,false);l.getBlockState(pos).useItemOn(crystal,l,p,InteractionHand.MAIN_HAND,hit);check(banner.aspect!=null&&crystal.getCount()==1,"actual crystal applies aspect consuming one"+color);var saved=banner.saveWithFullMetadata(p.registryAccess());var copy=new CrimsonBanner.Entity(pos,banner.getBlockState());copy.loadWithComponents(saved,p.registryAccess());check(copy.color==banner.color&&copy.aspect==banner.aspect,"color and aspect save/load"+color);var drops=Block.getDrops(banner.getBlockState(),l,pos,banner);check(drops.size()==1&&NoteData.tag(drops.get(0)).getByte("color")==color&&NoteData.tag(drops.get(0)).getString("aspect").equals(banner.aspect.getTag()),"breaking preserves colored aspect banner"+color);
   if(color==0){p.setShiftKeyDown(true);l.getBlockState(pos).useItemOn(crystal,l,p,InteractionHand.MAIN_HAND,hit);p.setShiftKeyDown(false);check(banner.aspect==null&&crystal.getCount()==1,"sneak clears aspect without consuming crystal");p.setGameMode(net.minecraft.world.level.GameType.CREATIVE);l.getBlockState(pos).useItemOn(crystal,l,p,InteractionHand.MAIN_HAND,hit);check(crystal.isEmpty()&&banner.aspect!=null,"original creative application still consumes crystal");p.setGameMode(net.minecraft.world.level.GameType.SURVIVAL);}
  }
  var cult=POS.offset(4,-2,-4);l.setBlock(cult,CrimsonContent.BANNER.get().defaultBlockState(),3);var crystal=LiquidDeath.crystal(Aspect.FIRE,2);p.setItemInHand(InteractionHand.MAIN_HAND,crystal);l.getBlockState(cult).useItemOn(crystal,l,p,InteractionHand.MAIN_HAND,new BlockHitResult(cult.getCenter(),Direction.UP,cult,false));check(((CrimsonBanner.Entity)l.getBlockEntity(cult)).color==-1&&((CrimsonBanner.Entity)l.getBlockEntity(cult)).aspect==null&&crystal.getCount()==2,"uncoloured cult banner rejects aspect application");var wall=POS.offset(4,-2,-7);l.setBlock(wall.east(),net.minecraft.world.level.block.Blocks.STONE.defaultBlockState(),3);var colored=CrimsonBanner.colored(10);p.setItemInHand(InteractionHand.MAIN_HAND,colored);((BlockItem)colored.getItem()).place(new BlockPlaceContext(p,InteractionHand.MAIN_HAND,colored,new BlockHitResult(wall.east().getCenter().add(-.5,0,0),Direction.WEST,wall.east(),false)));var tile=(CrimsonBanner.Entity)l.getBlockEntity(wall);check(tile!=null&&tile.wall&&tile.facing==4&&tile.color==10,"actual wall attachment facing preserves purple color");p.getAbilities().mayfly=true;p.getAbilities().flying=true;p.onUpdateAbilities();l.setDayTime(6000);l.setWeatherParameters(10000,0,false,false);p.connection.teleport(POS.getX()+2,POS.getY()+3,POS.getZ()-18,42,25);p.getInventory().clearContent();for(int i=0;i<9;i++)p.getInventory().setItem(i,CrimsonBanner.colored(i));passed=true;
 }
 @SubscribeEvent static void tick(net.neoforged.neoforge.client.event.ClientTickEvent.Post e){if(!Boolean.getBoolean("tc4modern.bannerAuditOnly"))return;var mc=net.minecraft.client.Minecraft.getInstance();if(mc.player==null||mc.level==null)return;ticks++;var server=mc.getSingleplayerServer();var id=mc.player.getUUID();if(ticks==80)server.execute(()->prepare(server.getPlayerList().getPlayer(id)));if(ticks==140){check(passed,"all16native crafts/placements/aspects complete");check(NoteData.tag(BasicsBookRecipes.researchIcon("BANNERS").stack()).getByte("color")==10,"original purple research icon");LiquidDeathAudit.shot(mc,"banners-sixteen-world.png");}if(ticks==160){var inv=mc.player.getInventory();var book=new ThaumonomiconScreen(new ThaumonomiconMenu(0,inv),inv,net.minecraft.network.chat.Component.empty());book.auditOpen(thaumcraft.api.research.ResearchCategories.getResearch("BANNERS"),0);mc.setScreen(book);}if(ticks==170)LiquidDeathAudit.shot(mc,"banners-book.png");if(ticks==180)mc.stop();}
}
